import worker from '/data/repo/_worker.js';

globalThis.fetch = () => Promise.resolve(new Response('', { status: 404, statusText: 'Not Found' }));

const pass = [];
const fail = [];

function check(name, cond) {
	if (cond) pass.push(name);
	else fail.push(name);
}

async function call(env, pathname, extra = {}) {
	const url = new URL('https://sub.example.workers.dev' + pathname);
	for (const [k, v] of Object.entries(extra)) url.searchParams.set(k, v);
	return worker.fetch(
		new Request(url.toString(), { headers: { 'User-Agent': 'v2ray' } }),
		env
	);
}

const decoded = async (r) => {
	const buf = await r.arrayBuffer();
	return atob(new TextDecoder().decode(buf));
};

// 1. Default TOKEN 'auto' when env.TOKEN unset -> quick subscription exported
let r = await call({}, '/auto');
check('default /auto works', r.status === 200 && (await decoded(r)).includes('vless://'));

// 2. Multiple TOKENs comma and comma+space separated
for (const t of ['sub1,sub2', 'beta1, beta2']) {
	for (const p of ['/sub1', '/sub2', '/beta1', '/beta2']) {
		r = await call({ TOKEN: t }, p);
		const body = await decoded(r);
		check(`TOKEN="${t}" path ${p}`, r.status === 200 && body.includes('vless://'));
	}
}

// non-listed token should be treated as custom-sub (400: host/uuid missing)
r = await call({ TOKEN: 'sub1,sub2' }, '/other');
check('non-token path not quick-sub', r.status === 400);

// 3. env.ADD -> static addresses prepended
r = await call({ ADD: '1.1.1.1#cn,2.2.2.2#cn' }, '/auto');
let body = await decoded(r);
check('ADD injects 1.1.1.1', body.includes('1.1.1.1'));
check('ADD injects 2.2.2.2', body.includes('2.2.2.2'));

// 4. LINK injected, comma separated joins with newline
r = await call({ LINK: 'vless://aaa-test,vless://bbb-test' }, '/auto');
body = await decoded(r);
check('LINK aaa present', body.includes('vless://aaa-test'));
check('LINK bbb present', body.includes('vless://bbb-test'));
check('LINK newline separated', body.includes('vless://aaa-test\nvless://bbb-test'));

// 5. PROXYIP override + ED=RPROXYIP cmliu path injection
r = await call({ PROXYIP: 'p1.test,p2.test', ED: 'cmliu', RPROXYIP: 'true' }, '/auto');
body = await decoded(r);
check('PROXYIP p1 or p2 used', body.includes('/proxyIP=p1.test') || body.includes('/proxyIP=p2.test'));

// 6. NOTLS + ADDNOTLS -> notls nodes included
r = await call({ NOTLS: 'true', ADDNOTLS: '9.9.9.9:80#cn' }, '/auto');
body = await decoded(r);
check('ADDNOTLS node present', body.includes('9.9.9.9') && body.includes('type=ws') && !body.includes('security=tls'));
check('default notls node present', body.includes('www.visa.com.sg'));

// 7. DLS parsing does not crash (numeric string)
r = await call({ DLS: '6' }, '/auto');
check('DLS numeric ok', r.status === 200);

// 8. ADDCSV / ADDAPI / ADDNOTLSAPI set -> no crash, upstream fetch stubbed
r = await call({ ADDCSV: 'https://x.example/a.csv', ADDAPI: 'https://x.example/a.txt', ADDNOTLSAPI: 'https://x.example/b.txt' }, '/auto');
check('ADD* URLs ok', r.status === 200);

// 9. ADD handles quotes/whitespace/newlines
r = await call({ ADD: '"5.5.5.5#cn" 6.6.6.6#cn,\n7.7.7.7#cn' }, '/auto');
body = await decoded(r);
check('ADD quote/space/newline split', body.includes('5.5.5.5') && body.includes('6.6.6.6') && body.includes('7.7.7.7'));

console.log(`PASS: ${pass.length}, FAIL: ${fail.length}`);
if (fail.length) {
	console.log('Failed:', fail.join('\n'));
	process.exit(1);
}

